import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"怨世","description":"","frontmatter":{"title":"怨世","date":"2026-11-24T00:00:00.000Z","seq":33,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"东方朔","source_book":"楚辞","prev":{"text":"沉江","link":"/blogs/楚辞/沉江.html"},"next":{"text":"七谏·怨思","link":"/blogs/楚辞/七谏·怨思.html"}},"headers":[],"relativePath":"blogs/楚辞/怨世.md","filePath":"blogs/楚辞/怨世.md"}'),o={name:"blogs/楚辞/怨世.md"};function l(n,a,c,m,z,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="怨世" tabindex="-1">怨世 <a class="header-anchor" href="#怨世" aria-label="Permalink to &quot;怨世&quot;">​</a></h1><p class="poem-meta">先秦 · 东方朔　·　七谏</p><div class="poem"><p class="poem-stanza">世沉淖而难论兮，俗岒峨而嵾嵯。</p><p class="poem-stanza">清泠泠而歼灭兮，溷湛湛而日多。</p><p class="poem-stanza">枭鸮既以成群兮，玄鹤弭翼而屏移。</p><p class="poem-stanza">蓬艾亲入御于床笫兮，马兰踸踔而日加。</p><p class="poem-stanza">弃捐药芷与杜衡兮，余柰世之不知芳何？</p><p class="poem-stanza">何周道之平易兮，然芜秽而险戏。</p><p class="poem-stanza">高阳无故而委尘兮，唐虞点灼而毁议。</p><p class="poem-stanza">谁使正其真是兮，虽有八师而不可为。</p><p class="poem-stanza">皇天保其高兮，后土持其久。</p><p class="poem-stanza">服清白以逍遥兮，偏与乎玄英异色。</p><p class="poem-stanza">西施媞媞而不得见兮，嫫母勃屑而日侍。</p><p class="poem-stanza">桂蠹不知所淹留兮，蓼虫不知徙乎葵菜。</p><p class="poem-stanza">处湣湣之浊世兮，今安所达乎吾志。</p><p class="poem-stanza">意有所载而远逝兮，固非众人之所识。</p><p class="poem-stanza">骥踌躇于弊輂兮，遇孙阳而得代。</p><p class="poem-stanza">吕望穷困而不聊生兮，遭周文而舒志。</p><p class="poem-stanza">宁戚饭牛而商歌兮，桓公闻而弗置。</p><p class="poem-stanza">路室女之方桑兮，孔子过之以自侍。</p><p class="poem-stanza">吾独乖剌而无当兮，心悼怵而耄思。</p><p class="poem-stanza">思比干之恲恲兮，哀子胥之慎事。</p><p class="poem-stanza">悲楚人之和氏兮，献宝玉以为石。</p><p class="poem-stanza">遇厉武之不察兮，羌两足以毕斮。</p><p class="poem-stanza">小人之居势兮，视忠正之何若？</p><p class="poem-stanza">改前圣之法度兮，喜嗫嚅而妄作。</p><p class="poem-stanza">亲谗谀而疏贤圣兮，讼谓闾娵为丑恶。</p><p class="poem-stanza">愉近习而蔽远兮，孰知察其黑白？</p><p class="poem-stanza">卒不得效其心容兮，安眇眇而无所归薄。</p><p class="poem-stanza">专精爽以自明兮，晦冥冥而壅蔽。</p><p class="poem-stanza">年既已过太半兮，然埳轲而留滞。</p><p class="poem-stanza">欲高飞而远集兮，恐离罔而灭败。</p><p class="poem-stanza">独冤抑而无极兮，伤精神而寿夭。</p><p class="poem-stanza">皇天既不纯命兮，余生终无所依。</p><p class="poem-stanza">愿自沉于江流兮，绝横流而径逝。</p><p class="poem-stanza">宁为江海之泥涂兮，安能久见此浊世？</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
